struct cardstate *cs = NULL;
struct usb_cardstate *ucs = NULL;
struct usb_endpoint_descriptor *endpoint;
int buffer_size;

gig_dbg(DEBUG_ANY, "%s: Check if device matches ...", __func__);

/* See if the device offered us matches what we can accept */
if ((le16_to_cpu(udev->descriptor.idVendor)  != USB_M105_VENDOR_ID) ||
    (le16_to_cpu(udev->descriptor.idProduct) != USB_M105_PRODUCT_ID)) {
	gig_dbg(DEBUG_ANY, "device ID (0x%x, 0x%x) not for me - skip",
		le16_to_cpu(udev->descriptor.idVendor),
		le16_to_cpu(udev->descriptor.idProduct));
	return -ENODEV;
}
if (hostif->desc.bInterfaceNumber != 0) {
	gig_dbg(DEBUG_ANY, "interface %d not for me - skip",
		hostif->desc.bInterfaceNumber);
	return -ENODEV;
}
if (hostif->desc.bAlternateSetting != 0) {
	dev_notice(&udev->dev, "unsupported altsetting %d - skip",
		   hostif->desc.bAlternateSetting);
	return -ENODEV;
}
if (hostif->desc.bInterfaceClass != 255) {
	dev_notice(&udev->dev, "unsupported interface class %d - skip",
		   hostif->desc.bInterfaceClass);
	return -ENODEV;
}

dev_info(&udev->dev, "%s: Device matched ... !\n", __func__);

/* allocate memory for our device state and initialize it */
cs = gigaset_initcs(driver, 1, 1, 0, cidmode, GIGASET_MODULENAME);
if (!cs)
	return -ENODEV;
ucs = cs->hw.usb;

/* save off device structure ptrs for later use */
usb_get_dev(udev);
ucs->udev = udev;
ucs->interface = interface;
cs->dev = &interface->dev;

/* save address of controller structure */
usb_set_intfdata(interface, cs);

endpoint = &hostif->endpoint[0].desc;

buffer_size = le16_to_cpu(endpoint->wMaxPacketSize);
ucs->bulk_out_size = buffer_size;
ucs->bulk_out_epnum = usb_endpoint_num(endpoint);
ucs->bulk_out_buffer = kmalloc(buffer_size, GFP_KERNEL);
if (!ucs->bulk_out_buffer) {
	dev_err(cs->dev, "Couldn't allocate bulk_out_buffer\n");
	retval = -ENOMEM;
	goto error;
}

ucs->bulk_out_urb = usb_alloc_urb(0, GFP_KERNEL);
if (!ucs->bulk_out_urb) {
	dev_err(cs->dev, "Couldn't allocate bulk_out_urb\n");
	retval = -ENOMEM;
	goto error;
}

endpoint = &hostif->endpoint[1].desc;

ucs->busy = 0;

ucs->read_urb = usb_alloc_urb(0, GFP_KERNEL);
if (!ucs->read_urb) {
	dev_err(cs->dev, "No free urbs available\n");
	retval = -ENOMEM;
	goto error;
}
buffer_size = le16_to_cpu(endpoint->wMaxPacketSize);
ucs->rcvbuf_size = buffer_size;
ucs->rcvbuf = kmalloc(buffer_size, GFP_KERNEL);
if (!ucs->rcvbuf) {
	dev_err(cs->dev, "Couldn't allocate rcvbuf\n");
	retval = -ENOMEM;
	goto error;
}
/* Fill the interrupt urb and send it to the core */
usb_fill_int_urb(ucs->read_urb, udev,
		 usb_rcvintpipe(udev, usb_endpoint_num(endpoint)),
		 ucs->rcvbuf, buffer_size,
		 gigaset_read_int_callback,
		 cs, endpoint->bInterval);

retval = usb_submit_urb(ucs->read_urb, GFP_KERNEL);
if (retval) {
	dev_err(cs->dev, "Could not submit URB (error %d)\n", -retval);
	goto error;
}

/* tell common part that the device is ready */
if (startmode == SM_LOCKED)
	cs->mstate = MS_LOCKED;

